const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const phoneColors=[{id:'burgundy',hex:'#713e49',zh:'勃艮第红',en:'Burgundy'},{id:'silver',hex:'#e4e4e5',zh:'银色',en:'Silver'},{id:'graphite',hex:'#303135',zh:'石墨黑',en:'Graphite'},{id:'blue',hex:'#aebcd3',zh:'雾蓝色',en:'Mist blue'}];
export const phoneColor=id=>phoneColors.find(c=>c.id===id)||phoneColors[3];
// Backend catalog variants own the exact shape and hardware colors.
// Supported contract: variants[colorId] = {overlay, mask, width, height}.
export function modelVariant(model,color){const c=phoneColor(color),variant=model.variants?.[c.id]||model.colors?.find?.(v=>v.id===c.id)||{};return {...model,...variant,name:model.name,brand:model.brand,phoneColor:c.id};}
export async function prepareModelColor(model,color){return modelVariant(model,color);}
let sheet;
export function mountPhoneSelector(host,{models,value='',color='blue',onChange,t}){
 let current=models.find(m=>m.name===value),shade=phoneColor(color),brand=current?.brand||models[0]?.brand,revision=0;
 function paint(){host.innerHTML=`<div class="phone-selection"><div class="phone-selection-row"><button type="button" data-phone-brand aria-haspopup="dialog"><span>${esc(brand)}</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></button><span class="phone-selection-divider"></span><button type="button" data-phone-model aria-haspopup="dialog"><span>${esc(current?.name||t('选择手机型号','Choose phone model'))}</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></button></div><div class="phone-color-options" role="group" aria-label="${t('机型颜色','Phone color')}">${phoneColors.map(c=>`<button type="button" data-phone-color="${c.id}" style="--phone-swatch:${c.hex}" aria-pressed="${shade.id===c.id}" aria-label="${esc(t(c.zh,c.en))}"><span></span></button>`).join('')}</div><p class="phone-color-label">${t(shade.zh,shade.en)}</p></div>`;host.querySelectorAll('[data-phone-brand],[data-phone-model]').forEach(b=>b.onclick=open);host.querySelectorAll('[data-phone-color]').forEach(b=>b.onclick=()=>{shade=phoneColor(b.dataset.phoneColor);paint();commit();});}
 async function commit(){if(!current)return;const version=++revision;host.setAttribute('aria-busy','true');const next=host.closest('dialog')?.querySelector('[data-home-model-next]')||document.querySelector('#next-step');if(next)next.disabled=true;try{const model=await prepareModelColor(current,shade.id);if(version!==revision)return;await onChange(model,shade.id);}finally{if(version===revision){host.removeAttribute('aria-busy');if(next?.isConnected&&current)next.disabled=false;}}}
 function open(){
  if(!sheet){sheet=document.createElement('dialog');sheet.className='phone-model-sheet';document.body.append(sheet);sheet.addEventListener('click',e=>{if(e.target===sheet){const r=sheet.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)sheet.close();}});}
  const opener=document.activeElement;sheet.setAttribute('aria-label',t('选择手机型号','Choose phone model'));
  function draw(){const options=models.filter(m=>m.brand===brand);if(brand==='Apple'){const rank=m=>Number(m.name.match(/\d+/)?.[0]||0)*10+(/Pro Max/.test(m.name)?5:/Pro/.test(m.name)?4:/Plus/.test(m.name)?3:/Mini|e$/.test(m.name)?0:2);options.sort((a,b)=>rank(b)-rank(a));}sheet.innerHTML=`<header class="phone-sheet-head"><h2>${t('选择手机型号','Choose phone model')}</h2><button type="button" data-phone-sheet-close aria-label="${t('关闭','Close')}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></header><div class="phone-brand-tabs" role="tablist" aria-label="${t('手机品牌','Phone brands')}">${[...new Set(models.map(m=>m.brand))].map(b=>`<button type="button" role="tab" data-picker-brand="${esc(b)}" aria-selected="${b===brand}" tabindex="${b===brand?0:-1}" aria-controls="phone-picker-results">${esc(b)}</button>`).join('')}</div><div class="phone-picker-results" id="phone-picker-results" role="tabpanel">${options.map(m=>`<button type="button" data-picker-model="${esc(m.name)}" aria-pressed="${m.name===current?.name}"><span>${esc(m.name)}</span>${m.name===current?.name?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>':''}</button>`).join('')}</div>`;sheet.querySelector('[data-phone-sheet-close]').onclick=()=>sheet.close();sheet.querySelectorAll('[data-picker-brand]').forEach(b=>b.onclick=()=>{brand=b.dataset.pickerBrand;draw();sheet.querySelector('[aria-selected=true]').focus();});sheet.querySelector('.phone-brand-tabs').onkeydown=e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...sheet.querySelectorAll('[data-picker-brand]')],i=tabs.findIndex(b=>b===document.activeElement);tabs[e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length].click();};sheet.querySelectorAll('[data-picker-model]').forEach(b=>b.onclick=()=>{current=models.find(m=>m.name===b.dataset.pickerModel);brand=current.brand;sheet.close();paint();commit();host.querySelector('[data-phone-model]')?.focus();});}
  draw();sheet.onclose=()=>{if(opener?.isConnected)opener.focus();};sheet.showModal();
 }
 paint();
}
window.PopomoPhoneModels={phoneColor,modelVariant,prepareModelColor};
